    // Store the view direction for bank calculations
    const dx = target.x - eye.x;
    const dy = target.y - eye.y;
    const dz = target.z - eye.z;
    const len = Math.sqrt(dx*dx + dy*dy + dz*dz);
    const d = { x: dx/len, y: dy/len, z: dz/len };

    function bank(up: Vec): void {
        // Project up onto the plane perpendicular to view direction
        const dot = up.x * d.x + up.y * d.y + up.z * d.z;
        const px = up.x - dot * d.x;
        const py = up.y - dot * d.y;
        const pz = up.z - dot * d.z;
        const pLen = Math.sqrt(px*px + py*py + pz*pz);

        // If the projection is too small, up is along the line of sight - keep previous roll
