        // Normalize the projected up and set it
        const nx = px / pLen;
        const ny = py / pLen;
        const nz = pz / pLen;

        camera.upVector.x = nx;
        camera.upVector.y = ny;
        camera.upVector.z = nz;
    }

    return { camera, bank };
}
